/* Image placeholder + resizable image extension styles using shadcn CSS variables */

/* ── Placeholder node ── */
.ext-image-placeholder {
  width: 100%;
}

.ext-image-placeholder-trigger {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem;
  border: none;
  border-radius: calc(var(--radius) - 2px);
  background: var(--accent);
  color: var(--accent-foreground);
  font-size: 0.875rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-image-placeholder-trigger > svg {
  width: 1.5rem;
  height: 1.5rem;
  flex-shrink: 0;
}

.ext-image-placeholder-trigger:hover {
  background: var(--secondary);
  color: var(--secondary-foreground);
}

.ext-image-placeholder-trigger--selected,
.ext-image-placeholder-trigger:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--ring);
}

.ext-image-placeholder-popover {
  width: 28rem;
  max-width: min(calc(100vw - 2rem), 28rem);
  padding: 0.75rem;
}

.ext-image-upload-zone {
  margin: 0.5rem 0;
  border: 1px dashed var(--border);
  border-radius: calc(var(--radius) - 2px);
  font-size: 0.875rem;
  transition:
    border-color 150ms ease-out,
    background-color 150ms ease-out;
}

.ext-image-upload-zone:hover {
  background: var(--secondary);
}

.ext-image-upload-zone--dragging {
  border-color: var(--primary);
  background: var(--secondary);
}

.ext-image-upload-zone--reject {
  border-color: var(--destructive);
  background: color-mix(in srgb, var(--destructive) 10%, transparent);
}

.ext-image-upload-label {
  display: flex;
  height: 7rem;
  width: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  cursor: pointer;
  user-select: none;
}

.ext-image-upload-label > svg {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0 auto 0.5rem;
  flex-shrink: 0;
}

.ext-image-embed {
  display: grid;
  gap: 0.5rem;
}

.ext-image-embed-submit.ext-image-embed-submit {
  width: 100%;
  border-color: transparent;
  background: var(--primary);
  color: var(--primary-foreground);
}

.ext-image-embed-submit.ext-image-embed-submit:hover {
  background: color-mix(in srgb, var(--primary) 85%, black);
  color: var(--primary-foreground);
}

.ext-image-error {
  margin: 0;
  font-size: 0.75rem;
  color: var(--destructive, #ef4444);
}

.ext-image-hint {
  margin: 0;
  text-align: center;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}

.ext-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ── Resizable image node ── */
.ext-image-view {
  position: relative;
  display: flex;
  flex-direction: column;
  width: fit-content;
  margin-block: 1rem;
  border-radius: calc(var(--radius) - 2px);
}

.ext-image-view--left {
  margin-right: auto;
}

.ext-image-view--center {
  margin-inline: auto;
}

.ext-image-view--right {
  margin-left: auto;
}

.ext-image-view--selected {
  box-shadow: 0 0 0 2px var(--ring);
}

.ext-image-view-img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: calc(var(--radius) - 2px);
}

.ext-image-view-caption {
  padding-top: 0.375rem;
  text-align: center;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

/* resize handles */
.ext-image-resize {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  width: 1rem;
  cursor: col-resize;
  touch-action: none;
}

.ext-image-resize--left {
  left: 0;
  justify-content: flex-start;
}

.ext-image-resize--right {
  right: 0;
  justify-content: flex-end;
}

.ext-image-resize-bar {
  width: 0.25rem;
  height: 4rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--foreground) 30%, transparent);
  opacity: 0;
  transition: opacity 150ms ease-out;
}

.ext-image-view:hover .ext-image-resize-bar,
.ext-image-view--resizing .ext-image-resize-bar {
  opacity: 1;
}

/* action bar — rendered in a portal (fixed) so it never gets clipped by
   overflow containers, tracked to the image's rect below/right of the node */
.ext-image-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--popover);
  color: var(--popover-foreground);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
}

.ext-image-actions--floating {
  position: fixed;
  margin-top: 0;
  z-index: 60;
  opacity: 1;
}

.ext-image-action-btn {
  width: 1.75rem;
  padding: 0;
}
